<?php
session_start();
if(!isset($_SESSION['user_id']) || $_SESSION['role']!='admin'){ header('Location: login.php'); exit; }
$data=json_decode(file_get_contents(__DIR__.'/fake_db.json'),true);
$comps=array_reverse($data['complaints']??[]);
if(isset($_GET['status']) && isset($_GET['id'])){
 $id=intval($_GET['id']); $ns=$_GET['status'];
 foreach($data['complaints'] as &$c){ if($c['id']==$id){ $c['status']=$ns; break; } }
 file_put_contents(__DIR__.'/fake_db.json',json_encode($data,JSON_PRETTY_PRINT));
 header('Location: admin_complaints.php'); exit;
}
?>
